from pathlib import Path
import re
base=Path('items')
def edit(i,fn):
 p=base/(i+'.md');s=p.read_text();t=fn(s);assert t!=s,i;p.write_text(t)
def adddeps(s,ds):
 old=re.search(r'^deps: \[([^\n]*)\]$',s,re.M);deps=re.findall(r'[a-z]+-[a-z0-9-]+',old.group(1));deps+= [d for d in ds if d not in deps];s=s[:old.start()]+ 'deps: ['+', '.join(deps)+']'+s[old.end():]
 role=re.search(r'^dependency_roles:\n((?:  [^\n]*\n)+)',s,re.M);extra=''.join('  '+d+': mathematical-premise\n' for d in ds if '  '+d+':' not in role.group(0));s=s[:role.end()]+extra+s[role.end():];return s
edit('def-gr-smooth-covariant-two-tensor-field',lambda s:s.replace('ranges over $a,b\\in\\{1,\\dots,n\\}$','ranges over the label set $I_n=\\{1,\\dots,n\\}$ (or the relabelled set\\n$I_4=\\{0,1,2,3\\}$ when $n=4$)'.replace('\\n','\n')).replace('Because the coordinate derivations at $q$ form a basis','For a coordinate tuple $z\\in x(U)$ define the **coordinate representative**\n$A^x_{ab}(z):=A_{ab}(x^{-1}(z))$. When the argument is a coordinate tuple,\n$A_{ab}(z)$ abbreviates this representative in the named chart; when it is a\npoint of $M$, it denotes the component function on the chart domain. Thus\n$A_{ab}(x(y^{-1}(u)))$ in a change-of-coordinates formula means\n$A^x_{ab}((x\\circ y^{-1})(u))$, never evaluation of a function on $M$ at a\ntuple. For $n=4$, $x^a$ and $\\partial_a$ mean the original coordinate and\nderivation labelled $a+1$, respectively; this relabels every slot and sum.\nThe label $0$ alone gives no coordinate vector a causal character.\n\nBecause the coordinate derivations at $q$ form a basis').replace('with $0$ the distinguished time index','with $0$ the time-coordinate label when such a coordinate is chosen'))
edit('lem-gr-covariant-two-tensor-transformation-law',lambda s:s.replace('let $A_{cd}$ and $A\'_{ab}$ denote the components of $A$ in the charts $x$ and\n$y$. Then for every $q\\in U\\cap V$, writing $y=q$ in the second chart,','let $A_{cd}$ and $A\'_{ab}$ denote their coordinate representatives in the\ncharts $x$ and $y$ as specified in [[def-gr-smooth-covariant-two-tensor-field]].\nFor $q\\in U\\cap V$ put $u=y(q)$ and write $x(u):=(x\\circ y^{-1})(u)$. Then').replace('\\sum_{c,d=1}^{n}','\\sum_{c,d\\in I_n}').replace('$$A\'_{ab}(y) =','$$A\'_{ab}(u) =').replace('}(y)\\,','}(u)\\,').replace('x(y)\\bigr),$$','x(u)\\bigr),$$').replace('$D(x\\circ y^{-1})(y)$','$D(x\\circ y^{-1})(u)$; $I_n$ is the label set of the supplier,\nso in dimension four the sum runs from $0$ through $3$').replace('the functions $A_{cd}\\circ x$ are smooth because $A_{cd}$ is smooth on the chart domain and $x$ is a homeomorphism of smooth charts','choose $(U,x)$ from the given atlas, so each $A^x_{cd}=A_{cd}\\circ x^{-1}$ is smooth on $x(U)$ by [L6], and $A^x_{cd}\\circ(x\\circ y^{-1})$ is smooth on $y(U\\cap V)$ by [L3]-[L4]'))
edit('def-gr-inverse-metric-and-musical-isomorphisms',lambda s:s.replace('\\delta^a{}_b=\\delta^c{}_bg^{ab}(q)','\\delta^a{}_b,\\qquad g_{ac}(q)g^{cb}(q)=\\delta_a{}^b'))
edit('lem-gr-inverse-metric-is-smooth',lambda s:s.replace('\\sum_{c,d=1}^{4}','\\sum_{c,d=0}^{3}').replace('where $\\partial y^a/\\partial x^c$ are the entries of $D(y\\circ x^{-1})$.','where every component evaluated at a coordinate tuple is its coordinate\nrepresentative, as in [[def-gr-smooth-covariant-two-tensor-field]],\n$x(u)$ denotes $(x\\circ y^{-1})(u)$, and $\\partial y^a/\\partial x^c$ are\nthe entries of $D(y\\circ x^{-1})$.').replace('hence the matrix-valued map $q\\mapsto(g_{ab}(q))$ is $C^\\infty$ with nowhere-vanishing determinant, and by [L2]','hence the coordinate representative $z\\mapsto(g_{ab}(x^{-1}(z)))$ on the open Euclidean set $x(U)$ is $C^\\infty$ with nowhere-vanishing determinant, and by [L2]'))
edit('lem-gr-connection-conditions-in-chart-components',lambda s:s.replace('\\sum_{d=1}^{4}','\\sum_{d=0}^{3}').replace('(a,b,c=1,\\dots,4)','(a,b,c=0,1,2,3)').replace('$\\partial_1|_p,\\dots,\\partial_4|_p$','$\\partial_0|_p,\\dots,\\partial_3|_p$'))
edit('ex-gr-spherical-coordinates-flat-metric-components',lambda s:s.replace('=-r^2\\sin\\vartheta','=r^2\\sin\\vartheta').replace('; consequently a smooth injective map whose derivative is invertible everywhere has open image and a smooth inverse','').replace('2.1 By steps 1.1-1.2 and [L2], $\\Phi(W)$ is open and $y=\\Phi^{-1}$ is smooth;','2.1 For every $u\\in W$, step 1.1 and [L2] give an open neighbourhood $O_u\\subseteq W$ such that $\\Phi|_{O_u}$ has open image $V_u$ and a smooth local inverse. The image $\\Phi(W)=\\bigcup_{u\\in W}V_u$ is open. By step 1.2, each local inverse equals the set-theoretic inverse $\\Phi^{-1}$ on $V_u$, so these inverses agree on overlaps and give a smooth global $y=\\Phi^{-1}$ on $\\Phi(W)$. This argument uses all available local inverse neighbourhoods and makes no family of choices;'))
